import pandas as pd

df = pd.read_excel('/root/data.xlsx', header=None)

# Find first row with meaningful data (e.g., "Turn" or numbers)
for index, row in df.iterrows():
    # Convert row to string and check for keywords or just print non-empty rows
    row_str = row.dropna().astype(str).tolist()
    if row_str:
        print(f"Row {index}: {row_str}")
    if index > 30:
        break

